-void MsgGenerateNowStr(nsACString& nowStr) {
-  char dateBuf[100];
-  dateBuf[0] = '\0';
-  PRExplodedTime exploded;
-  PR_ExplodeTime(PR_Now(), PR_LocalTimeParameters, &exploded);
-  PR_FormatTimeUSEnglish(dateBuf, sizeof(dateBuf), "%a %b %d %H:%M:%S %Y",
-                         &exploded);
-  nowStr.Assign(dateBuf);
-}
